export function buildRecordingSupplement() {
  const out = {};
  for (const [locale, values] of Object.entries(recordingSupplementRows)) {
    if (values.length !== recordingSupplementKeys.length) {
      throw new Error(`Invalid recording supplemental row ${locale}: ${values.length}/${recordingSupplementKeys.length}`);
    }
    out[locale] = Object.fromEntries(recordingSupplementKeys.map((key, index) => [key, values[index]]));
  }
  return out;
}
